insert into public.stops
  (name, slug, category, latitude, longitude, city, state, description, public_access, image, source, verified_at, opening_hours, website, phone, osm_type, osm_id, timezone)
values
  ('Albatwitch — Chickies Rock', 'albatwitch-chickies-rock', 'cryptids', 40.05231, -76.52491, 'West Hempfield Township', 'PA', 'Lancaster County folklore places the Albatwitch—a roughly four-foot hairy "apple-snitch" sometimes described as a miniature Bigfoot—in the woods surrounding Chickies Rock, where stories say it stole apples and threw the cores back at picnickers. The legend has been recorded in the area for generations and now has its own annual celebration; travelers can visit its traditional territory by hiking to the public Chickies Rock Overlook.', 'limited', null, 'https://susquehannagreenway.org/news-and-stories/susquehanna-greenway-ghouls-legends/', '2026-09-07T15:27:08.742137+00:00', null, null, null, null, null, 'America/New_York'),
  ('Beast of Busco', 'beast-of-busco', 'cryptids', 41.23583, -85.32519, 'Churubusco', 'IN', 'Churubusco''s signature legend began with reports of an enormous snapping turtle called Oscar in Fulk Lake, culminating in a highly publicized attempt to capture it in 1949. The town still embraces the "Beast of Busco" through Turtle Days and a large turtle statue in the community park, giving the cryptid story a clear public stop.', 'open', null, 'https://visitindiana.in.gov/listing/beast-of-busco/16069/', '2026-09-08T13:20:58.818667+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Front Yard Chainsaw Bigfoot', 'bigfoot', 'cryptids', 46.137069, -122.942008, 'Longview', 'WA', 'A twelve-foot Bigfoot carved from an evergreen stump by chainsaw artist Patrick Bryson in 2023, holding the house number. It stands in the front garden of a private home — view it from the road and do not enter the property.', 'private', null, 'https://www.roadsideamerica.com/tip/79870', '2026-09-05T12:48:08.486466+00:00', null, null, null, 'node', 9271115441, 'America/Los_Angeles'),
  ('Sherwood Bigfoot', 'bigfoot-2', 'cryptids', 45.36042, -122.856409, 'Sherwood', 'OR', 'A Bigfoot figure mapped beside a road in Sherwood, south-west of Portland. Nothing is published about who made it, when, or whether it stands on private ground — so treat it as a curiosity to look for rather than a destination, and do not go onto anyone''s property to find it.', 'roadside', null, 'https://www.openstreetmap.org/node/13670202967', null, null, null, null, 'node', 13670202967, 'America/Los_Angeles'),
  ('Bigfoot Discovery Museum', 'bigfoot-museum', 'cryptids', 37.041437, -122.072526, 'Felton', 'CA', 'A small roadside museum founded by longtime Bigfoot researcher Michael Rugg, holding footprint casts, local sighting reports, memorabilia and material relating to the Patterson-Gimlin film. Reported permanently closed — check before making the drive.', 'closed', null, 'https://www.roadsideamerica.com/story/17314', '2026-09-05T12:48:08.486466+00:00', null, 'https://www.bigfootdiscoveryproject.com/', '+1 831 335-4478', 'node', 797799539, 'America/Los_Angeles'),
  ('Bigfoot Statue', 'bigfoot-statue', 'cryptids', 40.93882, -123.628581, 'Willow Creek', 'CA', 'A standalone Bigfoot sculpture near Tonkin Park, one of several Sasquatch photo stops in the town that calls itself the Bigfoot Capital of the World. A roadside artwork rather than a staffed attraction.', 'roadside', null, 'https://mapcarta.com/N13526912734', '2026-09-05T12:48:08.486466+00:00', null, null, null, 'node', 13526912734, 'America/Los_Angeles'),
  ('Bigfoot Trap', 'bigfoot-trap', 'cryptids', 42.056587, -123.137225, 'Jackson County', 'OR', 'A genuine wooden trap, built in 1974 by the North American Wildlife Research Team after reports of enormous human-like tracks. Long since disarmed, it sits on the Collings Mountain Trail in Rogue River-Siskiyou National Forest, about three quarters of a mile from the trailhead — you walk in.', 'open', null, 'https://www.fs.usda.gov/media/162817', '2026-09-05T12:48:08.486466+00:00', null, null, null, 'node', 10817099005, 'America/Los_Angeles'),
  ('Chamber of Commerce Hodag', 'chamber-of-commerce-hodag', 'cryptids', 45.632178, -89.423039, 'Rhinelander', 'WI', 'Rhinelander''s larger-than-life Hodag, sculpted by local artist Tracy Goberville and standing outside the Area Chamber of Commerce. The toothy green monster is the city''s signature landmark and a free photo stop year round, celebrating a hoax from the 1890s that never quite went away.', 'roadside', null, 'https://explorerhinelander.com/articles/4-spots-to-see-hodags-on-your-next-visit-to-rhinelander/', '2026-09-05T12:48:08.486466+00:00', null, null, null, 'node', 2876677463, 'America/Chicago'),
  ('Champy Lake Monster Marker', 'champy-lake-monster-marker', 'cryptids', 44.70553, -73.40323, 'Plattsburgh', 'NY', 'This Legends & Lore marker on Cumberland Head commemorates Champ, the serpent-like creature allegedly seen in Lake Champlain for generations. More than 300 reported sightings have become part of regional folklore, and New York even symbolically protects the creature.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/10700-2/', '2026-09-07T16:22:52.387536+00:00', null, null, null, null, null, 'America/New_York'),
  ('Charles Mill Lake Monster', 'charles-mill-lake-monster', 'cryptids', 40.76533, -82.37155, 'Mifflin Township', 'OH', 'In 1959, three teenagers reported encountering a large armless humanoid with glowing green eyes and webbed feet near Charles Mill Lake, creating the legend of the Charles Mill Lake Monster. Charles Mill Marina has displayed the story for visitors behind its counter, giving the otherwise localized cryptid report a specific destination; the marina operates seasonally.', 'limited', null, 'https://www.richlandsource.com/2015/10/29/what-monster-lurks-at-charles-mill-lake/', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Elk River Bigfoot Statue', 'elk-river-bigfoot-statue', 'cryptids', 38.54886, -80.99986, 'Ivydale', 'WV', 'Clay County students built this roughly 10.5-foot, 1,800-pound Bigfoot sculpture for the Elk River Trail, giving the rail-trail its own Sasquatch landmark. The statue stands near Mile Marker 47 about two miles upstream from the Ivydale trailhead, so reaching it requires walking or biking the trail.', 'limited', null, 'https://wvtourism.com/west-virginia-paranormal-trail/', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('Expedition: Bigfoot! The Sasquatch Museum', 'expedition-bigfoot-the-sasquatch-museum', 'cryptids', 34.802273, -84.376175, 'Cherry Log', 'GA', 'Four thousand square feet given over entirely to Bigfoot: footprint casts, artifacts, life-size exhibits, sighting maps, photographs, a theatre, a reference library and a research vehicle. One of the most substantial dedicated Bigfoot attractions in the Southeast.', 'open', null, 'https://exploregeorgia.org/cherry-log/arts-culture/museums/expedition-bigfoot', '2026-09-05T12:48:08.486466+00:00', null, 'http://expeditionbigfoot.mdom.mobi/', '+1-706-946-2601', 'way', 380684000, 'America/New_York'),
  ('Ferry Fever', 'ferry-fever', 'cryptids', 47.566984, -122.630788, 'Bremerton', 'WA', 'A mural by Loc Hong at 532 5th Street, showing a Yeti taking a shower aboard a ferry against a backdrop of mountains — Pacific Northwest ferry culture crossed with cryptid humour. Visible from the street.', 'roadside', null, 'https://streetartcities.com/cities/seattle/markers/d3d8e61a-825e-4173-945e-4142ef7f5103', '2026-09-05T12:48:08.486466+00:00', null, null, null, 'node', 12672661145, 'America/Los_Angeles'),
  ('Gonzalez Bigfoot Statue', 'gonzalez-bigfoot-statue', 'cryptids', 40.939748, -123.631694, 'Willow Creek', 'CA', 'A Bigfoot-themed roadside artwork in Willow Creek, California''s self-proclaimed Bigfoot Country. A quick photo stop near the centre of town and the Willow Creek-China Flat Museum rather than a full attraction.', 'roadside', null, 'https://mapcarta.com/N13531160722', '2026-09-05T12:48:08.486466+00:00', null, null, null, 'node', 13531160722, 'America/Los_Angeles'),
  ('Hairy Women of Klipnocky Marker', 'hairy-women-of-klipnocky-marker', 'cryptids', 42.4277, -77.80109, 'Canaseraga', 'NY', 'Local legend says two girls disappeared into the Klipnocky forest after being told to hide there for safety and were later reported as large, hairy women living in the woods. The story was in circulation by the 1920s, and today a Legends & Lore marker on County Route 13C gives travelers a specific public-road stop tied to the tale.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/a-hairy-legend/', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hodag Statue, Rhinelander', 'hodag', 'cryptids', 45.655123, -89.400556, 'Rhinelander', 'WI', 'One of the many Hodags around Rhinelander — the horned, clawed beast Eugene Shepard claimed to have captured in 1893, later admitted as a hoax and adopted by the city as its emblem ever since. This one stands about two miles from the better-known Chamber of Commerce Hodag, so it is a second stop rather than the same one twice.', 'roadside', null, 'https://explorerhinelander.com/articles/take-a-hodag-tour-of-rhinelander/', null, null, null, null, 'node', 7815427682, 'America/Chicago'),
  ('Hoop Snake Hill Marker', 'hoop-snake-hill-marker', 'cryptids', 41.27935, -74.29825, 'Chester', 'NY', 'Generations of Warwick-area folklore describe an enormous snake that grabs its own tail, forms a hoop and rolls downhill toward its victims before striking with a spiked tail. The legend now has a dedicated marker overlooking the area associated with the creature.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/hoop-snake-hill/', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('Jersey Devil Coaster', 'jersey-devil', 'cryptids', 40.13439, -74.443789, 'Jackson', 'NJ', 'A single-rail roller coaster at Six Flags Great Adventure themed on the Pine Barrens legend: 130 feet, an 87-degree drop and three inversions. Park admission is required, so this is a day out rather than a roadside stop.', 'limited', null, 'https://www.sixflags.com/greatadventure/attractions/jersey-devil-coaster', '2026-09-05T12:48:08.486466+00:00', null, 'https://www.sixflags.com/greatadventure/attractions/jersey-devil-coaster', null, 'node', 12859899266, 'America/New_York'),
  ('Lake Champlain Monster Monument', 'lake-champlain-monster-monument', 'cryptids', 44.47347, -73.22155, 'Burlington', 'VT', 'A waterfront monument recognizes Champ, the long-necked creature said to inhabit Lake Champlain. Reports and legends surrounding Champ stretch back generations, making the lake monster one of the Northeast''s best-known cryptids even though no conclusive evidence has established its existence.', 'open', null, 'https://www.atlasobscura.com/places/lake-champlain-monster-monument', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Loveland Frogman Riverfront', 'loveland-frogman-riverfront', 'cryptids', 39.26984, -84.25816, 'Loveland', 'OH', 'The Loveland Frogman, a human-sized frog-like creature associated with the Little Miami River, has been part of local folklore since reported encounters beginning in 1955. Loveland now treats the creature as an official city mascot, and Nisbet Park gives travelers a public riverfront stop directly tied to the legend and the city''s recurring Return of the Frogman celebration.', 'open', null, 'https://lovelandoh.gov/491/City-Mascot', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lucille''s Jersey Devil Statue', 'lucilles-jersey-devil-statue', 'cryptids', 39.7426, -74.3701, 'Warren Grove', 'NJ', 'A winged Jersey Devil figure stands outside Lucille''s Luncheonette along Route 539 in the Pine Barrens. The restaurant embraces local Pine Barrens folklore, making the sculpture a useful physical stop for travelers following the legend of the Leeds Devil.', 'roadside', null, 'https://www.lucillescountrycooking.com/', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lyonesse River Monster Marker', 'lyonesse-river-monster-marker', 'cryptids', 43.61615, -75.35691, 'Lyons Falls', 'NY', 'Lyonesse is a supposed 15-foot river creature first famously reported in the Black River in 1951, described as dark brown with unusual fins and silver-colored eyes. The town installed a Legends & Lore marker beside the river, making this unusually obscure New York cryptid easy to visit.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/lyonesse/', '2026-09-07T16:22:52.387536+00:00', null, null, null, null, null, 'America/New_York'),
  ('Maryland Goatman at Governor''s Bridge', 'maryland-goatman-at-governors-bridge', 'cryptids', 38.95143, -76.69346, 'Bowie', 'MD', 'Governor''s Bridge is one of the locations most closely tied to Maryland''s Goatman legend, the half-man, half-goat creature said to stalk the woods and roads around Prince George''s County. The 1912 bridge itself is closed to vehicle traffic, so use the nearby public natural-area access and do not enter neighboring private property or wander the area after posted hours.', 'limited', null, 'https://historicbridges.org/bridges/browser/?bridgebrowser=maryland/governorsbridge/', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Michigan Dogman — Mystery Town USA', 'michigan-dogman-mystery-town-usa', 'cryptids', 45.77956, -84.73281, 'Mackinaw City', 'MI', 'Michigan''s Dogman is a long-running canine-humanoid legend that became especially famous through northern Michigan storytelling and radio culture. Mystery Town USA gives the creature a real, legal destination through a dedicated Dogman exhibit inside its walkthrough of cryptids, UFOs and other mysteries.', 'open', null, 'https://mysterytownusa.com/portfolio-items/michigan-dogman/', '2026-09-08T14:53:55.160019+00:00', null, 'https://mysterytownusa.com/', null, null, null, 'America/Detroit'),
  ('Mothman Museum', 'mothman-museum', 'cryptids', 38.842731, -82.138529, 'Point Pleasant', 'WV', 'Point Pleasant spent thirteen months in 1966 and 1967 reporting a winged figure with red eyes, and it has never really stopped. The museum keeps the newspaper clippings, the witness statements and props from the film adaptation in one small storefront on Main Street, a short walk from the statue.', 'open', null, 'https://www.mothmanmuseum.com/', '2026-09-06T01:56:28.154232+00:00', 'Mo-Th 10:00-17:00; Fr-Sa 10:00-18:00; Su 12:00-17:00; Dec 25 off; Jan 1 off; Nov Th[4] off; easter off', 'https://www.mothmanmuseum.com/', '+1-304-812-5211', 'way', 904768521, 'America/New_York'),
  ('Mothman Statue', 'mothman-statue', 'cryptids', 38.842573, -82.13852, 'Point Pleasant', 'WV', 'Bob Roach''s twelve-foot stainless-steel Mothman, installed downtown in 2003 and now one of the best-known cryptid landmarks in the country. It stands beside the Mothman Museum and is free to visit day or night.', 'roadside', null, 'https://visitpointpleasantwv.com/see-do/', '2026-09-05T12:48:08.486466+00:00', null, null, null, 'node', 5328446004, 'America/New_York'),
  ('Museum Bigfoot Statue', 'museum-bigfoot-statue', 'cryptids', 40.940121, -123.632084, 'Willow Creek', 'CA', 'An outdoor Bigfoot statue at the Community Commons, alongside the Willow Creek-China Flat Museum and the visitor information point. Another easy photo stop while working through the town''s Bigfoot landmarks.', 'roadside', null, 'https://www.willowcreekcsd.com/community-commons/', '2026-09-05T12:48:08.486466+00:00', null, null, null, 'node', 13527671968, 'America/Los_Angeles'),
  ('North American Bigfoot Center', 'north-american-bigfoot-center', 'cryptids', 45.431789, -122.340251, 'Boring', 'OR', 'A museum and research centre founded by Bigfoot researcher Cliff Barackman, with footprint casts, historical artifacts, films and a life-size Sasquatch. The gift shop and information area are free; the exhibit halls charge admission.', 'open', null, 'https://traveloregon.com/things-to-do/oregon-attractions/museums/north-american-bigfoot-center/', '2026-09-05T12:48:08.486466+00:00', null, null, null, 'node', 8868908017, 'America/Los_Angeles'),
  ('Origin of Champ Marker', 'origin-of-champ-marker', 'cryptids', 44.03611, -73.45666, 'Port Henry', 'NY', 'Bulwagga Bay is one of the locations most closely associated with Champ, the legendary creature of Lake Champlain. The marker here preserves a local origin story in which a scorned suitor becomes the lake monster, while Port Henry has built a much broader identity around decades of alleged Champ sightings.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/origin-of-champ/', '2026-09-07T16:22:52.387536+00:00', null, null, null, null, null, 'America/New_York'),
  ('Otis the Fishing Sasquatch', 'otis-the-fishing-sasquatch', 'cryptids', 38.41535, -86.7601, 'French Lick', 'IN', 'Otis is a 25-foot wooden Sasquatch built by Bear Hollow Wood Carvers in 2023 and posed on a broken dock with an enormous fishing pole. He stands on the French Lick Cabins at Patoka Lake property and has become a destination in his own right, but visitors should remember that the surrounding cabins are an operating lodging property.', 'limited', null, 'https://www.roadsideamerica.com/tip/84642', '2026-09-08T13:53:25.695107+00:00', null, 'https://frenchlickcabins.net/', null, null, null, 'America/Indiana/Vincennes'),
  ('Peninsula Python Mural', 'peninsula-python-mural', 'cryptids', 41.2397, -81.55402, 'Peninsula', 'OH', 'In 1944, reports of a roughly 15-to-18-foot snake supposedly loose around Peninsula triggered searches and national attention, although the Peninsula Python was never found. The large 1964 mural on the front of Peninsula Library maps the winding Cuyahoga River valley and has become physically associated with the monster-snake legend, making it an easy public stop in town.', 'open', null, 'https://peninsulalibrary.org/about/mural/', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Pope Lick Monster — Pope Lick Park', 'pope-lick-monster-pope-lick-park', 'cryptids', 38.18781, -85.48466, 'Louisville', 'KY', 'Louisville folklore tells of a goat-man creature said to inhabit the area around the Pope Lick railroad trestle. The trestle is active railroad property and has been the site of fatal accidents, so OddWay should route travelers to public Pope Lick Park for the legend and never onto the tracks or bridge.', 'open', null, 'https://www.atlasobscura.com/places/the-pope-lick-monster', '2026-09-08T14:15:10.228298+00:00', null, 'https://louisvilleky.gov/government/parks/park-list/pope-lick-park', null, null, null, 'America/Kentucky/Louisville'),
  ('Salt Fork Bigfoot Search', 'salt-fork-bigfoot-search', 'cryptids', 40.10593, -81.52868, 'Jefferson Township', 'OH', 'Salt Fork State Park is one of Ohio''s best-known Bigfoot areas, with decades of reported sightings of the creature sometimes called the Ohio Grassman. Salt Fork Lodge actively embraces the legend: visitors can pick up a Bigfoot sightings map at the front desk and search the surrounding public park trails, and the lodge hosts the annual Ohio Bigfoot Conference.', 'open', null, 'https://www.saltforkparklodge.com/things-to-do/onsite-activities', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bloomfield Sasquatch', 'sasquatch', 'cryptids', 42.531314, -83.315132, 'Bloomfield', 'MI', 'A Sasquatch figure in Bloomfield Township, mapped close to the historic Franklin Cider Mill on Franklin Road. No artist, date or owner is recorded anywhere we can find. Visible from the road; the cider mill itself is the reason most people are on that stretch.', 'roadside', null, 'https://mapcarta.com/N12664732006', null, null, null, null, 'node', 12664732006, 'America/Detroit'),
  ('Sol Duc Sasquatch', 'sasquatch-2', 'cryptids', 47.98701, -124.393304, 'Clallam County', 'WA', 'A Sasquatch figure in the forest of Clallam County, mapped near the Sol Duc river east of Forks — deep in the country the Patterson-Gimlin era made famous. Nothing is published about it. Forest roads out here are remote and seasonal, so check conditions before going looking.', 'roadside', null, 'https://mapcarta.com/N7316891219', null, null, null, null, 'node', 7316891219, 'America/Los_Angeles'),
  ('Sasquatch Outpost', 'sasquatch-outpost', 'cryptids', 39.406045, -105.475045, 'Bailey', 'CO', 'A Bigfoot-themed shop and visitor attraction in Bailey, home to the Sasquatch Encounter Discovery Museum. Exhibits cover sightings, evidence, research and Colorado''s own Sasquatch stories, with a substantial gift shop attached.', 'open', null, 'https://www.colorado.com/bailey/attractions-entertainment/museums/sasquatch-outpost', '2026-09-05T12:48:08.486466+00:00', null, null, null, 'way', 129813715, 'America/Denver'),
  ('Sasquatch - Photo Opp', 'sasquatch-photo-opp', 'cryptids', 37.036099, -88.271112, 'Livingston County', 'KY', 'A roadside Sasquatch photo opportunity near Kentucky Lake and Grand Rivers. A pose-and-go cryptid stop rather than a museum.', 'roadside', null, 'https://mapcarta.com/N12893412684', '2026-09-05T12:48:08.486466+00:00', null, null, null, 'node', 12893412684, 'America/Chicago'),
  ('Sasquatch Pushing Over a House', 'sasquatch-pushing-over-a-house', 'cryptids', 47.664314, -122.319674, 'Seattle', 'WA', 'Richard Beyer''s 1982 sculpture at University Playground: a full-size aluminium Sasquatch leaning into a brightly painted house frame and apparently pushing it over. Free and always there.', 'open', null, 'https://en.wikipedia.org/wiki/Sasquatch_Pushing_Over_a_House', '2026-09-05T12:48:08.486466+00:00', null, null, null, 'node', 3211770268, 'America/Los_Angeles'),
  ('Sasquatch Statue', 'sasquatch-statue', 'cryptids', 48.995582, -122.75162, 'Blaine', 'WA', 'A 3,500-pound concrete Sasquatch, six foot eight, standing downtown near the Welcome Center. Installed as a town landmark and free to visit at any hour.', 'roadside', null, 'https://blainebythesea.com/sasquatch-statue/', '2026-09-05T12:48:08.486466+00:00', null, null, null, 'node', 10065644288, 'America/Los_Angeles'),
  ('Silver Lake Sea Serpent Marker', 'silver-lake-sea-serpent-marker', 'cryptids', 42.70068, -78.02302, 'Silver Lake', 'NY', 'Stories of a monster in Silver Lake became so popular that a local hotel owner built a mechanical sea serpent in 1855 and secretly launched it into the water to attract tourists. The hoax was eventually exposed, but the Silver Lake serpent survived as local folklore and now has its own Legends & Lore marker.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/sea-serpent-legend/', '2026-09-07T16:22:52.387536+00:00', null, null, null, null, null, 'America/New_York'),
  ('Skunk Ape Research Headquarters', 'skunk-ape-center-and-museum', 'cryptids', 25.893918, -81.278523, 'Ochopee', 'FL', 'An Everglades stop devoted to Florida''s Skunk Ape, the swamp-dwelling cryptid often called the Southeast''s Bigfoot. Based at Trail Lakes Campground, it collects sighting reports, lore and research alongside a well-stocked gift counter.', 'open', null, 'https://www.skunkape.info/', '2026-09-05T12:48:08.486466+00:00', null, 'https://www.skunkape.info/', null, 'node', 10210835917, 'America/New_York'),
  ('Southern Oregon Bigfoot Experience', 'southern-oregon-bigfoot-experience', 'cryptids', 42.167613, -123.646048, 'Cave Junction', 'OR', 'A Bigfoot museum, gift shop and roadside attraction with footprint casts, alleged hair samples, regional sighting accounts and a large Bigfoot statue outside. Yeti''s Ice Cream & Treats is attached.', 'open', null, 'https://sobfe.com/', '2026-09-05T12:48:08.486466+00:00', null, 'https://sobfe.com/', null, 'node', 11343789706, 'America/Los_Angeles'),
  ('Surfing Sasquatch', 'surfing-sasquatch', 'cryptids', 44.979731, -124.013634, 'Lincoln City', 'OR', 'A hand-carved wooden Sasquatch riding a surfboard, which is exactly right for the Oregon Coast. It stands at the Surfland Hotel — hotel property rather than a public park, so be considerate about photographs.', 'roadside', null, 'https://mapcarta.com/N13021851179', '2026-09-05T12:48:08.486466+00:00', null, null, null, 'node', 13021851179, 'America/Los_Angeles'),
  ('The Cryptozoology & Paranormal Museum', 'the-cryptozoology-paranormal-museum', 'cryptids', 36.433169, -77.916204, 'Littleton', 'NC', 'The Cryptozoology & Paranormal Museum is a small Littleton museum devoted to Bigfoot, ghosts and other unexplained phenomena. Visitors can see footprint casts, reportedly haunted objects and paranormal displays, with separate ghost hunts and Bigfoot-related outings offered at times.', 'open', null, 'https://crypto-para.org/', '2026-09-05T22:12:28.444612+00:00', null, null, null, 'way', 606784641, 'America/New_York'),
  ('Mission Ridge Yeti', 'the-yeti', 'cryptids', 47.275547, -120.428416, 'Wenatchee', 'WA', 'An eleven-foot metal Yeti high on Mission Ridge near the Liberator Express chairlift, welded from steel, recycled tire chains and scrap. The chain "fur" was designed to catch snow and frost. Reaching it means getting up the mountain, so this is a ski-area visit rather than a roadside stop.', 'limited', null, 'https://www.visitwenatchee.org/blog/behind-the-mission-ridge-yeti-three-years-later', '2026-09-05T12:48:08.486466+00:00', null, null, null, 'node', 9634773055, 'America/Los_Angeles'),
  ('TNT Area', 'tnt-area', 'cryptids', 38.92977, -82.07616, 'Point Pleasant', 'WV', 'The abandoned World War II explosives complex north of Point Pleasant is inseparable from the original Mothman story, with many early sightings reported around the old TNT bunkers in 1966–67. Portions can be explored on foot, but the former industrial landscape includes remediated Superfund land and mixed property boundaries, so visitors should stay on established public paths.', 'limited', null, 'https://www.atlasobscura.com/places/tnt-area', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Wampahoofus Trail', 'wampahoofus-trail', 'cryptids', 44.50574, -72.84764, 'Underhill', 'VT', 'This rugged Mount Mansfield trail is named for the wampahoofus, a mythical Green Mountain creature said to have legs shorter on one side so it could circle steep hillsides. Reaching the trail requires a mountain hike from the Stevensville area, and mud, snow and ice can make access seasonal.', 'limited', null, 'https://www.atlasobscura.com/places/wampahoofus-trail', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Willow Creek-China Flat Museum & Bigfoot Collection', 'willow-creek-china-flat-museum-bigfoot-collection', 'cryptids', 40.94025, -123.632115, 'Willow Creek', 'CA', 'A seasonal local-history museum holding one of the area''s most important Bigfoot collections: footprint casts, photographs, historical documents and material from researcher Bob Titmus. It sits a short distance from Bluff Creek, where the Patterson-Gimlin film was shot in 1967.', 'limited', null, 'https://www.thebigfootmuseum.com/', '2026-09-05T12:48:08.486466+00:00', 'Seasonal', 'https://www.thebigfootmuseum.com/', null, 'node', 12892684891, 'America/Los_Angeles'),
  ('Woodbooger Statue and Sanctuary', 'woodbooger-statue-and-sanctuary', 'cryptids', 36.91951, -82.62718, 'Norton', 'VA', 'After Animal Planet''s Finding Bigfoot filmed in Southwest Virginia, Norton embraced its local Bigfoot-like creature known as the Woodbooger and designated Flag Rock Recreation Area as a Woodbooger Sanctuary. A large creature statue now stands just beyond the parking area on the footpath toward Flag Rock Overlook.', 'open', null, 'https://www.nortonva.gov/455/Woodbooger-Sanctuary', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Yolo the Jackpotalope', 'yolo-the-jackalope', 'cryptids', 41.133566, -104.82535, 'Cheyenne', 'WY', 'A painted eight-foot boot outside the WyoLotto office in Cheyenne, carrying Yolo — the lottery''s jackalope mascot, and a nod to Wyoming''s horned-rabbit folklore. Whether there is a standalone jackalope statue here is unconfirmed.', 'roadside', null, 'https://wyolotto.com/', null, null, null, null, 'node', 14090479377, 'America/Denver'),
  ('Alderson Lion Historical Marker', 'alderson-lion-historical-marker', 'folklore', 37.72538, -80.64115, 'Alderson', 'WV', 'This marker preserves the bizarre local story of "French," a lion kept in Alderson between 1890 and 1894 after being adopted from a traveling circus. According to the marker, the lion was allowed to roam until it frightened a salesman into the Greenbrier River, prompting the town to require lions to be leashed.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/alderson-lion/', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('American Society of Dowsers Headquarters', 'american-society-of-dowsers-headquarters', 'folklore', 44.40934, -72.13748, 'Danville', 'VT', 'The American Society of Dowsers maintains its headquarters in Danville for practitioners of the centuries-old practice of using rods, pendulums and other methods to locate water or other hidden targets. The organization remains active in 2026, although the headquarters should be treated as a limited-access organizational stop rather than a walk-in museum.', 'limited', null, 'https://dowsers.org/', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ann Arbor Fairy Doors', 'ann-arbor-fairy-doors', 'folklore', 42.27856, -83.75019, 'Ann Arbor', 'MI', 'Tiny decorative doors began appearing around Ann Arbor after artist Jonathan B. Wright created miniature ''fairy'' entrances in the 1990s and early 2000s. Several public examples survive around downtown buildings and shops, creating a walkable scavenger hunt for miniature architecture.', 'open', null, 'https://www.atlasobscura.com/places/ann-arbor-s-fairy-doors', '2026-09-08T15:38:13.436959+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Avon Haunted Bridge', 'avon-haunted-bridge', 'folklore', 39.7579, -86.41402, 'Avon', 'IN', 'The railroad bridge west of Indianapolis has accumulated several local ghost stories, most famously involving a mother and child and another tale about a worker supposedly entombed in the structure. The bridge remains an active railroad structure, so OddWay visitors should view it only from legal public areas around Washington Township Park and never walk on the tracks.', 'roadside', null, 'https://visitindiana.in.gov/blog/post/5-weird-wonderful-must-see-places-near-indy/', '2026-09-08T13:20:58.818667+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Axe Murder Hollow', 'axe-murder-hollow', 'folklore', 42.03042, -80.15298, 'Millcreek Township', 'PA', 'For generations, Erie-area teenagers called the woods off Thomas Road "Axe Murder Hollow," telling stories about an axe murderer and ghosts haunting the hollow. Erie Reader''s archival investigation found no evidence that the legendary family massacre occurred; much of the old hollow is now residential private property, so experience the location only from public roads and **do not enter the woods or neighboring property**.', 'private', null, 'https://www.eriereader.com/article/exhuming-the-hollow', '2026-09-07T15:27:08.742137+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bartlesville Gravity Hill', 'bartlesville-gravity-hill', 'folklore', 36.668327, -95.988965, 'Bartlesville', 'OK', 'A stretch of Gap Road near the railway tracks where cars in neutral appear to climb. The legend blames children killed in a school bus crash, pushing vehicles clear of the rails. Someone took a level to it: the road runs downhill.', 'roadside', null, 'https://www.greencountryok.com/listing/gravity-hill/1608/', '2026-09-06T22:43:52.581802+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Blue Mist Road Trail', 'blue-mist-road-trail', 'folklore', 40.62551, -80.00662, 'Pine Township', 'PA', 'The closed section of Irwin Road through Irwin Run Conservation Area is better known as Blue Mist Road, a longstanding Pittsburgh-area urban-legend location associated with ghosts, strange lights and a blue-tinged mist. The old road is now primarily a walking and biking trail rather than a spooky drive; the usual route is about 3.8 miles out and back, and the more sensational stories remain folklore rather than established history.', 'limited', null, 'https://myhikes.org/trails/blue-mist-road-trail', '2026-09-07T15:27:08.742137+00:00', null, null, null, null, null, 'America/New_York'),
  ('Blue Sulphur Springs Pavilion', 'blue-sulphur-springs-pavilion', 'folklore', 37.82791, -80.63852, 'Blue Sulphur Springs', 'WV', 'This Greek Revival pavilion is the lone major survivor of a nineteenth-century resort built around a mineral spring once advertised for its healing properties. After extensive restoration, the pavilion was rededicated in 2023 and is now open to the public daily during posted daytime hours.', 'open', null, 'https://greenbrierhistorical.org/preservation/blue-sulphur-springs-pavillion/', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('Bonneville Boulevard Gravity Hill', 'bonneville-boulevard-gravity-hill-salt-lake-city-ut', 'folklore', 40.78944, -111.87917, 'Salt Lake City', 'UT', 'Stop on Bonneville Boulevard, looping around Memory Grove, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Denver'),
  ('Bunny Man Bridge', 'bunny-man-bridge', 'folklore', 38.78989, -77.36238, 'Clifton', 'VA', 'This narrow railroad overpass on Colchester Road became the center of Northern Virginia''s Bunny Man legend after reports of a man in a rabbit suit threatening people with an axe or hatchet circulated in 1970. The bridge remains an active public road, so view it while passing through or from a safe legal spot nearby and never stop inside the one-lane tunnel or trespass along the tracks.', 'roadside', null, 'https://www.fotospot.com/attractions/virginia/bunny-man-bridge', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Buzzard Roost', 'buzzard-roost', 'folklore', 41.21561, -81.70902, 'Hinckley Township', 'OH', 'Hinckley has celebrated the supposed annual return of turkey vultures every March since the 1950s, creating one of Ohio''s strangest recurring local traditions. Buzzard Roost in Hinckley Reservation is the public viewing area associated with the event, where Cleveland Metroparks continues to welcome visitors looking for the returning birds.', 'open', null, 'https://www.clevelandmetroparks.com/parks/visit/parks/hinckley-reservation/buzzard-roost', '2026-09-08T01:52:19.873287+00:00', null, null, null, null, null, 'America/New_York'),
  ('Cat Rocks Treasure Marker', 'cat-rocks-treasure-marker', 'folklore', 41.2454, -74.28533, 'Southfields', 'NY', 'Local legend says Revolutionary War loyalist and outlaw Claudius Smith hid stolen valuables inside caves at nearby Cat Rocks before his capture and execution. Treasure hunters have searched for the supposed cache for generations, and a Legends & Lore marker along Route 17 records the story; do not leave public access areas to hunt for it.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/cat-rocks-treasure/', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('Cave of Kelpius', 'cave-of-kelpius', 'folklore', 40.0238, -75.2016, 'Philadelphia', 'PA', 'Tradition connects this stone-lined chamber in the Wissahickon to Johannes Kelpius and his seventeenth-century community of mystics, who believed the end of the world was imminent. Historians debate whether the structure was actually Kelpius''s cave or a later springhouse, but visitors can reach it on foot from the public park trails.', 'limited', null, 'https://www.atlasobscura.com/places/cave-of-kelpius', '2026-09-08T02:24:39.058393+00:00', null, null, null, null, null, 'America/New_York'),
  ('Chained Rock', 'chained-rock', 'folklore', 36.75384, -83.70176, 'Pineville', 'KY', 'Pineville folklore says residents chained an enormous boulder to Pine Mountain to keep it from rolling down and crushing the town. The chain was actually installed in the 1930s as a publicity stunt inspired by the legend, and visitors can hike to the rock from Pine Mountain State Resort Park.', 'open', null, 'https://www.atlasobscura.com/places/chained-rock', '2026-09-08T14:30:49.642487+00:00', null, null, null, null, null, 'America/New_York'),
  ('Church of the Atonement Cemetery', 'church-of-the-atonement-cemetery', 'folklore', 38.73475, -76.82288, 'Brandywine', 'MD', 'A small cemetery and surviving steps are all that remain of the Church of the Atonement, built in the 19th century and demolished decades after services ended. The isolated burial ground has accumulated witch and ghost folklore over the years; access is awkward near the railroad, so use only legitimate approaches and never cross active tracks unsafely.', 'limited', null, 'https://www.atlasobscura.com/places/church-of-the-atonement-cemetery', '2026-09-08T03:48:11.440333+00:00', null, null, null, null, null, 'America/New_York'),
  ('Copperton Gravity Hill', 'copperton-gravity-hill-copperton-ut', 'folklore', 40.56611, -112.089028, 'Copperton', 'UT', 'Stop on State Route 48, under the train bridge, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Denver'),
  ('Cornwallis Cave', 'cornwallis-cave', 'folklore', 37.23503, -76.50513, 'Yorktown', 'VA', 'For generations, local tradition claimed British General Cornwallis used this riverside cave as his headquarters during the 1781 Siege of Yorktown. Historians have since rejected that story and identify the cave as a later ammunition-storage site, making the debunked legend itself part of the stop; the opening is gated and should not be entered.', 'open', null, 'https://www.nps.gov/york/learn/historyculture/cornwallis-cave.htm', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Cumberland Falls Moonbow and Lover''s Leap', 'cumberland-falls-moonbow-and-lovers-leap', 'folklore', 36.83973, -84.34452, 'Corbin', 'KY', 'Cumberland Falls is one of the few places where visitors can regularly see a lunar rainbow, or moonbow, under the right full-moon conditions. The surrounding gorge also carries the Lover''s Leap ghost story of a bride said to have fallen to her death and later appeared in a white dress near the falls.', 'open', null, 'https://www.kentuckytourism.com/events/hauntedkentucky', '2026-09-08T14:15:10.228298+00:00', null, 'https://parks.ky.gov/explore/cumberland-falls-state-resort-park-7786', null, null, null, 'America/New_York'),
  ('Cursed Self-Rocking Cradle', 'cursed-self-rocking-cradle', 'folklore', 37.41382, -79.14416, 'Lynchburg', 'VA', 'According to an 1839 Lynchburg legend, this mahogany cradle repeatedly rocked with no one touching it and would begin moving when a local minister challenged the unseen force to rock it. The actual cradle resurfaced through descendants of its original owners and was donated to the Lynchburg Museum in 2021, where visitors can now see the artifact behind the story.', 'open', null, 'https://lynchburgmuseum.org/2021-10-1-the-early-family-rocking-cradle/', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Devil Anse Hatfield Grave', 'devil-anse-hatfield-grave', 'folklore', 37.70447, -81.99245, 'Sarah Ann', 'WV', 'Hatfield clan patriarch Anderson “Devil Anse” Hatfield is buried in the family cemetery beneath a life-size marble statue imported from Italy. The cemetery is publicly visited as part of Hatfield-McCoy heritage tourism, but reaching the graves requires a steep climb and visitors should use care on the slope.', 'limited', null, 'https://www.hmdb.org/m.asp?Result=1&m=49912', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Devil''s Backbone Marker', 'devils-backbone-marker', 'folklore', 39.6258, -84.6705, 'Camden', 'OH', 'This rocky cliff along Paint Creek has been called the Devil''s Backbone since at least 1877 and has accumulated stories involving Bigfoot, hidden mines, missing skunks and a supposed curse. A Legends & Lore marker now stands at Herbert & Patricia Wagers Memorial Park, where visitors can also use the public walking and hiking trails.', 'open', null, 'https://www.wgpfoundation.org/historic-markers/devils-backbone/', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Devil''s Tower', 'devils-tower', 'folklore', 40.93381, -73.93322, 'Alpine', 'NJ', 'This stone tower was built in the early twentieth century as part of an estate near the Palisades. Local legend claims the ghost of the owner''s wife haunts the tower and that driving around it backward can summon her, but the structure is on private property and should only be viewed from the public road.', 'roadside', null, 'https://www.atlasobscura.com/places/devils-tower-alpine-new-jersey', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Devil''s Tree', 'devils-tree', 'folklore', 40.63034, -74.58266, 'Bernards Township', 'NJ', 'A solitary oak in a public park has accumulated stories involving curses, unexplained warmth and supposed hangings. Historical evidence does not support many of the more sensational claims, but the tree remains one of New Jersey''s best-known pieces of local supernatural folklore.', 'open', null, 'https://www.atlasobscura.com/places/devils-tree', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Devou Park Gravity Hill', 'devou-park-gravity-hill-covington-ky', 'folklore', 39.08583, -84.52944, 'Covington', 'KY', 'Stop on Devou Park, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/New_York'),
  ('Dummerston Vine', 'dummerston-vine', 'folklore', 42.93529, -72.57698, 'Dummerston', 'VT', 'A nineteenth-century legend blamed the deaths of several members of the Spaulding family on a cursed vine creeping through their cemetery plot. The story likely grew from tuberculosis deaths, but the row of family graves in Dummerston Center Cemetery remains the physical location connected with the tale.', 'open', null, 'https://www.atlasobscura.com/places/dummerston-vine', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Dunn''s Bridge', 'dunns-bridge', 'folklore', 41.22015, -86.96897, 'Wheatfield', 'IN', 'This unusual steel bridge over the Kankakee River carries a persistent local story that some of its metal came from the original 1893 Chicago World''s Fair Ferris wheel. The bridge itself is real and historically significant, while the Ferris-wheel connection is best treated as legend rather than settled fact.', 'open', null, 'https://www.hmdb.org/m.asp?m=269431', '2026-09-08T13:34:34.826362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Dyer Gravity Hill', 'dyer-gravity-hill-dyer-ar', 'folklore', 35.50139, -94.1476389, 'Dyer', 'AR', 'Stop on just outside Dyer, near Alma, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Edna Collins Covered Bridge', 'edna-collins-covered-bridge', 'folklore', 39.7275, -86.97633, 'Clinton Falls', 'IN', 'The 1922 Edna Collins Covered Bridge crosses Little Walnut Creek and carries one of Putnam County''s persistent ghost stories. Local legend tells of a girl named Edna who would wait for her parents to honk three times at the bridge and is now supposedly connected to unexplained sounds and sightings around the structure.', 'roadside', null, 'https://ourhistoricalindiana.blogspot.com/2020/11/edna-collings-bridge.html', '2026-09-08T13:20:58.818667+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Elijah Bond''s Ouija Board Grave', 'elijah-bonds-ouija-board-grave', 'folklore', 39.31036, -76.60674, 'Baltimore', 'MD', 'Elijah Bond patented the talking board that would become the Ouija board in 1891. His grave in Green Mount Cemetery was unmarked for decades until researchers installed a new headstone in 2008 with a full Ouija board carved into its reverse side; visit only during cemetery hours.', 'open', null, 'https://elijahbond.com/', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Esperance Witch Marker', 'esperance-witch-marker', 'folklore', 42.76087, -74.26119, 'Esperance', 'NY', 'Local legend tells of a widowed French woman accused of witchcraft by neighboring settlers during the nineteenth century. The story claims she was eventually shot through her window with a silver bullet and buried beneath a pine tree so she could not return, and a Legends & Lore marker now preserves the tale along Route 20.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/esperance-witch/', '2026-09-07T16:22:52.387536+00:00', null, null, null, null, null, 'America/New_York'),
  ('Face in the Rock', 'face-in-the-rock', 'folklore', 46.4374, -86.81683, 'Au Train', 'MI', 'A weathered human face carved into the sandstone along Lake Superior has become one of the Upper Peninsula''s stranger shoreline landmarks. Local interpretation connects the carving with a nineteenth-century story involving a French voyageur and an Ojibwe leader, although the exact origin of the carving is not firmly documented; reaching it requires a shoreline walk.', 'limited', null, 'https://www.michigan.org/article/road-trip/one-tank-road-trip-central-upper-peninsula', '2026-09-08T15:12:49.285859+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Fairy Stone State Park', 'fairy-stone-state-park', 'folklore', 36.78439, -80.09372, 'Stuart', 'VA', 'The park is famous for naturally occurring staurolite crystals shaped like crosses, which local legend says formed from the tears of fairies who learned of Christ''s crucifixion. Visitors can hike, camp and search designated areas for the distinctive stones while the state park interprets both the geology and folklore.', 'open', null, 'https://www.dcr.virginia.gov/state-parks/fairy-stone', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fell Family Cemetery', 'fell-family-cemetery', 'folklore', 39.282, -76.59452, 'Baltimore', 'MD', 'The family that gave Fell''s Point its name once had a burial ground here, now reduced to a tiny graveyard squeezed between later Baltimore buildings. Very little remains above ground, and uncertainty over what happened to some of the burials has helped make the small plot a recurring stop in neighborhood ghost lore.', 'open', null, 'https://www.atlasobscura.com/places/fells-family-cemetery', '2026-09-08T03:48:11.440333+00:00', null, null, null, null, null, 'America/New_York'),
  ('Footprints of the Archangel Gabriel', 'footprints-of-the-archangel-gabriel', 'folklore', 38.12996, -87.93482, 'New Harmony', 'IN', 'New Harmony tradition once claimed that the Archangel Gabriel visited communal leader George Rapp in 1819 and left footprints impressed into a limestone slab. The weathered slab still survives behind a brick wall near Church and Main Streets, but it is on private property and should only be viewed from the public sidewalk through or over the wall.', 'private', null, 'https://www.roadsideamerica.com/story/19391', '2026-09-08T13:20:58.818667+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Franklin Spring Marker', 'franklin-spring-marker', 'folklore', 43.00845, -73.8436, 'Ballston Spa', 'NY', 'In 1869, Spiritualist Samuel Hides said a séance message from the spirit of Benjamin Franklin told him exactly where to drill for a healing mineral spring. A spring was struck at the predicted depth, and the story became part of Ballston Spa folklore; a Legends & Lore marker now identifies the site.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/franklin-spring/', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('Fred Clifton Park Overlook - Lover''s Leap', 'fred-clifton-park-overlook-lover-s-leap', 'folklore', 36.720258, -80.325434, 'Stuart', 'VA', 'A wooded mountaintop park at about 2,930 feet with several overlook platforms and picnic tables. It carries the same Lover''s Leap story as the Route 58 pull-off nearby, but this is the park viewpoint rather than the highway one — they are two distinct stops.', 'open', null, 'https://visitpatrickcounty.org/parks-and-trails/fred-clifton-park/', '2026-09-06T22:43:52.581802+00:00', null, null, null, null, null, 'America/New_York'),
  ('Freeman Gravity Hill', 'freeman-gravity-hill-freeman-mo', 'folklore', 38.57972, -94.5943889, 'Freeman', 'MO', 'Stop on Route D at East 299th Street, near the Kansas line, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Gapland Road Gravity Hill', 'gapland-road-gravity-hill-burkittsville-md', 'folklore', 39.396861, -77.63444, 'Burkittsville', 'MD', 'Stop on Gapland Road, West Main Street, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/New_York'),
  ('Garden Creek Gravity Hill', 'garden-creek-gravity-hill-casper-wy', 'folklore', 42.773722, -106.3329722, 'Casper', 'WY', 'Stop on Garden Creek Road, near the Rotary Park entrance, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Denver'),
  ('Gates of Hell', 'gates-of-hell', 'folklore', 40.01839, -83.01199, 'Columbus', 'OH', 'A large storm-drain tunnel beneath North High Street has acquired the nickname Gates of Hell and a collection of urban legends involving deaths, strange noises and supposedly supernatural encounters. The tunnel itself is drainage infrastructure and should not be entered; treat this as a view-from-public-ground folklore stop only.', 'roadside', null, 'https://www.atlasobscura.com/places/gates-of-hell', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('Ghost Lake on Shades of Death Road', 'ghost-lake-on-shades-of-death-road', 'folklore', 40.92532, -74.89997, 'Knowlton Township', 'NJ', 'This small lake beside the famously named Shades of Death Road developed its eerie name from mist that rises from the water on cool mornings. The surrounding road has accumulated decades of murder tales, ghost stories and supernatural folklore; visitors should use the designated state-forest parking area rather than stop in traffic.', 'roadside', null, 'https://www.nj.gov/dep/parksandforests/maps/jennyjump-trail.pdf', '2026-09-08T17:48:18.566953+00:00', null, null, null, null, null, 'America/New_York'),
  ('Golden Gate Park Gravity Hill', 'golden-gate-park-gravity-hill-san-francisco-ca', 'folklore', 37.770426, -122.480647, 'San Francisco', 'CA', 'Stop on JFK Drive, where water from Rainbow Falls appears to run towards Lloyd Lake, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('Gorton Turtle Marker', 'gorton-turtle-marker', 'folklore', 42.86158, -75.352, 'West Edmeston', 'NY', 'A Brookfield-area tall tale tells of a turtle larger than a cottage emerging from Gorton Lake and dragging an impossibly heavy wagon of rocks into the water. A Legends & Lore marker on Gorton Lake Road preserves the story at a specific roadside location.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/gorton-turtle/', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('Grave of the Female Stranger', 'grave-of-the-female-stranger', 'folklore', 38.79985, -77.05652, 'Alexandria', 'VA', 'A white marble table tomb in St. Paul''s Cemetery marks the grave of an unidentified 23-year-old woman who died in Alexandria in 1816. Her true identity remains unknown and later legends have connected her to figures such as Theodosia Burr Alston; the grave is the third on the right after entering the St. Paul''s section and should be visited respectfully during cemetery hours.', 'open', null, 'https://www.alexandriava.gov/index.php/historic-alexandria/womens-history-in-alexandria', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Gravity Hill', 'gravity-hill', 'folklore', 42.547073, -90.233213, 'Shullsburg', 'WI', 'A rural stretch of County Road U south of Shullsburg, just past Rennick Road, where a slight descent reads as a climb. A car in neutral appears to roll backwards uphill. The effect is well documented and entirely optical.', 'roadside', null, 'https://walworth.extension.wisc.edu/gravity-hill/', '2026-09-06T22:43:52.581802+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Gravity Hill - Folklore Destination', 'gravity-hill-folklore-destination', 'folklore', 35.582997, -80.245116, 'Richfield', 'NC', 'A gravity hill on Richfield Road where a car left in neutral appears to roll uphill, because the surrounding land hides the road''s true slope. The local story credits the ghosts of a mother and child killed there, complete with handprints said to appear on cars.', 'roadside', null, 'https://www.wral.com/archive/14764496/', '2026-09-06T22:43:52.581802+00:00', null, null, null, null, null, 'America/New_York'),
  ('Gravity Hill Lane', 'gravity-hill-lane-oak-grove-al', 'folklore', 33.2036944, -86.30806, 'Oak Grove', 'AL', 'Stop on Gravity Hill Lane, in Talladega County, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Gravity Hill', 'gravity-hill-new-paris', 'folklore', 39.9856, -78.6486, 'New Paris', 'PA', 'Put the car in neutral at the marked spot on Gravity Hill Road and it rolls, slowly, in the wrong direction. The surrounding hills hide the true horizon well enough that your eyes lose the argument with the road. Bring a bottle of water to pour out and watch. There are two such stretches in the area.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:56:28.154232+00:00', null, null, null, null, null, 'America/New_York'),
  ('Green Man''s Tunnel', 'green-mans-tunnel', 'folklore', 40.27259, -79.96914, 'South Park Township', 'PA', 'Western Pennsylvania''s Green Man legend grew from the real life of Raymond Robinson, a badly disfigured man whose nighttime walks inspired generations of frightening stories about a glowing figure called Charlie No-Face. The legend was later attached to this abandoned railroad tunnel even though Robinson did not live there; view the tunnel from the legal road or trail area and do not enter blocked infrastructure or storage areas.', 'roadside', null, 'https://www.atlasobscura.com/places/green-man-s-tunnel', '2026-09-08T02:24:39.058393+00:00', null, null, null, null, null, 'America/New_York'),
  ('Greenbrier Ghost Historical Marker', 'greenbrier-ghost-historical-marker', 'folklore', 37.98912, -80.413, 'Smoot', 'WV', 'This roadside marker commemorates the extraordinary 1897 Greenbrier Ghost case, in which Zona Heaster Shue''s mother claimed her daughter''s ghost revealed that Zona had been murdered. The resulting murder conviction made the story one of America''s most famous cases in which alleged supernatural testimony played a role in bringing attention to a crime.', 'roadside', null, 'https://wvencprod.wvnet.edu/entries/2107', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('Greenbrier Valley Theatre', 'greenbrier-valley-theatre', 'folklore', 37.80017, -80.44284, 'Lewisburg', 'WV', 'Greenbrier Valley Theatre keeps the Greenbrier Ghost story alive through performances and displays connected with the famous Zona Heaster Shue case. The theatre is an active arts venue, so interior access follows box-office and performance schedules rather than open exploration.', 'limited', null, 'https://wvtourism.com/west-virginia-paranormal-trail/', '2026-09-08T03:30:19.766632+00:00', null, null, null, null, null, 'America/New_York'),
  ('Haeger''s Vision Marker', 'haegers-vision-marker', 'folklore', 42.14329, -73.88886, 'Germantown', 'NY', 'According to local tradition, Rev. Johann Frederick Haeger was visited on Christmas Eve 1720 by a spirit calling itself the "Master of Time and Space." The spirit supposedly showed him visions of Germantown''s future, and a Legends & Lore marker now identifies the location tied to the story.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/haegers-vision/', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('Harry S. Thobe Ghost Marker', 'harry-s-thobe-ghost-marker', 'folklore', 39.50051, -84.74575, 'Oxford', 'OH', 'Harry Thobe was a stonemason and famous Miami University superfan who built the house at this location and maintained a stone fountain on campus until his death in 1950. Legend says that calling Thobe''s name near the former fountain site may produce an answering echo; the Legends & Lore marker is at his former Chestnut Street home, so view it from the public right-of-way and do not disturb the residence.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/harry-s-thobe/', '2026-09-08T01:49:16.338406+00:00', null, null, null, null, null, 'America/New_York'),
  ('Headless Horseman Marker', 'headless-horseman-marker', 'folklore', 41.09097, -73.86119, 'Sleepy Hollow', 'NY', 'Sleepy Hollow Cemetery and the adjoining Old Dutch Church landscape are inseparable from Washington Irving''s The Legend of Sleepy Hollow. A Legends & Lore marker inside the cemetery specifically commemorates the story that the Headless Horseman tethers his horse among the graves.', 'open', null, 'https://www.wgpfoundation.org/historic-markers/headless-horseman/', '2026-09-07T16:22:52.387536+00:00', null, null, null, null, null, 'America/New_York'),
  ('Helltown at Boston Mill', 'helltown-at-boston-mill', 'folklore', 41.26259, -81.56031, 'Boston Township', 'OH', 'Federal land purchases around the former village of Boston in the 1970s left vacant buildings that helped fuel later urban legends about "Helltown," including stories of satanic churches, chemical disasters and mutant creatures. Most of the sensational landmarks described in those stories are gone or were never what the legends claimed, so Boston Mill Visitor Center in Cuyahoga Valley National Park is the legal public anchor for the story and visitors should not trespass on closed structures or private land.', 'open', null, 'https://en.wikipedia.org/wiki/Helltown,_Ohio', '2026-09-08T01:52:19.873287+00:00', null, null, null, null, null, 'America/New_York'),
  ('Henry''s Hill', 'henry-s-hill-mount-hope-al', 'folklore', 34.4300278, -87.5054444, 'Mount Hope', 'AL', 'Stop on Henry''s Hill, in Lawrence County, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Hoodoo Marker', 'hoodoo-marker', 'folklore', 39.45928, -76.41388, 'Kingsville', 'MD', 'This rough boundary stone has stood beside Bel Air Road since the early 1800s and carries a biblical warning cursing anyone who moves a neighbor''s landmark. It sits beside private commercial property near the roadside, so view it without blocking traffic or treating the surrounding land as public.', 'roadside', null, 'https://www.roadsideamerica.com/tip/3345', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Hopkins Hall Handprint', 'hopkins-hall-handprint', 'folklore', 40.00098, -83.0116, 'Columbus', 'OH', 'Ohio State folklore says an art student became trapped in a Hopkins Hall elevator overnight and left frantic handprints behind while trying to escape. Versions of the story claim a mysterious handprint still reappears on the exterior of the building; the site is on a public university campus, though visitors should not disrupt classes or enter closed spaces looking for it.', 'open', null, 'https://artsandsciences.osu.edu/news/campus-legends-horrors-and-lore', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('House of Many Crosses — Harrison Mayes', 'house-of-many-crosses-harrison-mayes', 'folklore', 36.60508, -83.71966, 'Middlesboro', 'KY', 'Coal miner and self-taught folk artist Henry Harrison Mayes spent decades creating concrete crosses, hearts and religious messages that he distributed across America and envisioned sending around the world. He also constructed his Middlesboro home itself in the shape of a cross; it remains a private residence, with surviving original crosses visible from the public street.', 'private', null, 'https://folk-visions.com/marker/middlesboro-ky-house-of-many-crosses/', '2026-09-08T14:42:00.461026+00:00', null, null, null, null, null, 'America/New_York'),
  ('Jacob Conklin Pirate Legend Marker', 'jacob-conklin-pirate-legend-marker', 'folklore', 40.75868, -73.38299, 'Wheatley Heights', 'NY', 'Long Island legend says Jacob Conklin sailed with Captain William Kidd before building a home in this area around 1710. The house burned in 1918, but a Legends & Lore marker on Colonial Springs Road preserves the local pirate connection.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/jacob-conklin/', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('Jennings Hall — Hill House Inspiration', 'jennings-hall-hill-house-inspiration', 'folklore', 42.92037, -73.23583, 'North Bennington', 'VT', 'This secluded stone mansion on the Bennington College campus is often identified as a possible visual inspiration for Shirley Jackson''s The Haunting of Hill House. The connection is literary lore rather than proven fact, but Jackson lived in North Bennington and the building''s isolated setting closely fits the association.', 'limited', null, 'https://www.atlasobscura.com/places/jennings-hall', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Joe Road Gravity Hill', 'joe-road-gravity-hill-stockbridge-wi', 'folklore', 44.02806, -88.3071389, 'Stockbridge', 'WI', 'Stop on Joe Road, south of Stockbridge off WIS 55, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Chicago'),
  ('John Henry Historical Park', 'john-henry-historical-park', 'folklore', 37.64958, -80.76673, 'Talcott', 'WV', 'The park commemorates the legendary steel-driving man John Henry and the story of his race against a steam drill during construction of the nearby Big Bend Tunnel. Visitors now find a large John Henry statue, interpretive displays and walking areas at the location traditionally associated with the legend.', 'open', null, 'https://www.johnhenrypark.com/', '2026-09-08T03:11:33.200322+00:00', null, null, null, null, null, 'America/New_York'),
  ('John Quincy Adams Summer Home Legend Marker', 'john-quincy-adams-summer-home-legend-marker', 'folklore', 40.76154, -73.33565, 'Deer Park', 'NY', 'For decades, local stories claimed President John Quincy Adams once owned a summer home in Deer Park. Research instead traced the property to a different John Quincy Adams, a clergyman who owned land here in the nineteenth century, and a Legends & Lore marker now explains how the presidential connection became local folklore.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/john-quincy-adams/', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('Johnny Appleseed Grave', 'johnny-appleseed-grave', 'folklore', 41.11223, -85.12244, 'Fort Wayne', 'IN', 'John Chapman, better known as Johnny Appleseed, died near Fort Wayne in 1845 after decades of planting and tending orchards across the frontier. A prominent memorial in Johnny Appleseed Park marks the burial place traditionally accepted as his grave, giving the American folk figure a real public destination.', 'open', null, 'https://www.atlasobscura.com/places/grave-of-johnny-appleseed', '2026-09-08T13:34:34.826362+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Judgement Street Gravity Hill', 'judgement-street-gravity-hill-shullsburg-wi', 'folklore', 42.5475, -90.23333, 'Shullsburg', 'WI', 'Stop on Judgement Street, just past Rennick Road, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Kagel Canyon Gravity Hill', 'kagel-canyon-gravity-hill-sylmar-ca', 'folklore', 34.3045833, -118.3755, 'Sylmar', 'CA', 'Stop on Kagel Canyon Road, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('Kau-Qua-Tau Witch Legend Marker', 'kau-qua-tau-witch-legend-marker', 'folklore', 42.83366, -78.74749, 'West Seneca', 'NY', 'A Legends & Lore marker at Ebenezer Cemetery preserves the story of Kau-Qua-Tau, a Seneca woman accused of witchcraft in 1821 and killed after fleeing the accusation. Later folklore blamed her spirit for disturbances in a cabin that once stood at the site.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/kau-qua-tau/', '2026-09-07T16:22:52.387536+00:00', null, null, null, null, null, 'America/New_York'),
  ('King Memorial Gravity Hill', 'king-memorial-gravity-hill-kirtland-hills-oh', 'folklore', 41.64125, -81.2956389, 'Kirtland Hills', 'OH', 'Stop on King Memorial Road, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lake Drummond and the Phantom Lovers', 'lake-drummond-and-the-phantom-lovers', 'folklore', 36.60283, -76.46974, 'Chesapeake', 'VA', 'Lake Drummond lies deep within the Great Dismal Swamp and has inspired generations of supernatural stories, most famously the Phantom Lovers tale of a young man searching the lake for his dead bride. Reaching the lake requires using refuge roads, trails or waterways rather than a normal roadside pull-off, and access can vary with refuge conditions.', 'limited', null, 'https://www.fws.gov/refuge/great-dismal-swamp', '2026-09-08T04:02:08.563059+00:00', null, null, null, null, null, 'America/New_York'),
  ('Legend of Jenny Jump', 'legend-of-jenny-jump', 'folklore', 40.900861, -74.956664, 'Hope Township', 'NJ', 'The Jenny Jump legend as told inside Land of Make Believe, where an old house tied to the story is preserved. Around 1748 a nine-year-old girl was cornered on a rocky height and her father shouted "Jump, Jenny, jump". Note this is inside the ticketed park, not at Jenny Jump State Forest.', 'limited', null, 'https://www.lomb.com/group-trips/', '2026-09-06T22:43:52.581802+00:00', null, null, null, null, null, 'America/New_York'),
  ('Legend of June Lake Slot Machines', 'legend-of-june-lake-slot-machines', 'folklore', 37.799244, -119.06356, 'Mammoth Lakes', 'CA', 'A roadside marker shaped like a slot machine, complete with handle and reels, telling the story that June Lake''s illegal 1930s machines were dumped in the lake ahead of a state revenue raid. Installed around 2010. Divers have looked more than once and found nothing.', 'roadside', null, 'https://www.hmdb.org/m.asp?m=37585', '2026-09-06T22:43:52.581802+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('Legend of Ondessonk', 'legend-of-ondessonk', 'folklore', 37.517881, -88.754435, 'Vienna', 'IL', 'A memorial inside Camp Ondessonk, the southern Illinois Catholic youth camp founded in 1959 and named for the Huron name given to St Isaac Jogues, meaning bird of prey. Not an open roadside stop: the camp admits day hikers from mid-August to mid-May during set hours and closes the grounds entirely in summer.', 'limited', null, 'https://www.ondessonk.com/camping-hiking/hiking-biking/', '2026-09-06T22:43:52.581802+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Legend of the Moon', 'legend-of-the-moon', 'folklore', 47.663388, -122.121976, 'Redmond', 'WA', 'A monumental cedar carving by Dudley Carter, made in 1977 from a 35-foot, six-ton section of old-growth cedar, interpreting a Coast Salish story of Moon the Transformer. Permanently installed near the entrance to Marymoor Park.', 'open', null, 'https://www.4culture.org/public_art/legend-of-the-moon/', '2026-09-06T22:43:52.581802+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('Lichau Road Gravity Hill', 'lichau-road-gravity-hill-rohnert-park-ca', 'folklore', 38.342361, -122.62028, 'Rohnert Park', 'CA', 'Stop on Lichau Road, on the western slope of Sonoma Mountain, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('Loma Alta Gravity Hill', 'loma-alta-gravity-hill-altadena-ca', 'folklore', 34.2000278, -118.1218333, 'Altadena', 'CA', 'Stop on East Loma Alta Drive, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('Lost Children of the Alleghenies Monument', 'lost-children-of-the-alleghenies-monument', 'folklore', 40.29476, -78.60351, 'Pavia', 'PA', 'Brothers George and Joseph Cox disappeared from their Bedford County home in 1856 and were found dead in the mountains after a massive search, a tragedy later surrounded by stories of a local man''s prophetic dreams helping locate them. A stone memorial now stands near the place they were found, reached by a rough seasonal dirt road and a short walk into State Game Lands 26.', 'limited', null, 'https://pabucketlist.com/visiting-the-lost-children-of-the-alleghenies-monument-in-bedford-county/', '2026-09-08T02:24:39.058393+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lova''s Dollhouse Grave', 'lovas-dollhouse-grave', 'folklore', 39.63843, -85.56499, 'Arlington', 'IN', 'The grave of young Lova Cline is marked by an elaborate miniature house built by her family rather than a conventional headstone. Local stories later attached eerie details to the little structure, including claims that objects inside change position, making it one of Indiana''s better-known unusual cemetery monuments.', 'open', null, 'https://www.roadsideamerica.com/story/59389', '2026-09-08T13:20:58.818667+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Lover''s Leap', 'lover-s-leap', 'folklore', 34.684831, -94.363664, 'Mena', 'AR', 'A hiking destination at the end of the 1.5-mile Lover''s Leap Trail in Queen Wilhelmina State Park, on Rich Mountain in the Ouachitas. The park still uses the trail for guided nature and history walks.', 'open', null, 'https://www.arkansasstateparks.com/trails/lovers-leap-trail', '2026-09-06T22:43:52.581802+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Lover''s Leap Lookout', 'lover-s-leap-lookout', 'folklore', 38.119628, -81.118475, 'Ansted', 'WV', 'A rocky overlook above the New River and marina at Hawks Nest State Park, normally reached by a short trail from behind the lodge. The local telling has a couple from opposing groups, forbidden to marry, leaping together. West Virginia State Parks currently lists the Lovers Leap trail as closed after extensive storm damage — check before you go, because the overlook is only reachable by that trail.', 'closed', null, 'https://wvstateparks.com/park/hawks-nest-state-park/', null, null, null, null, null, null, 'America/New_York'),
  ('Lover''s Leap Overlook', 'lover-s-leap-overlook', 'folklore', 36.701944, -82.743131, 'Duffield', 'VA', 'A viewpoint on the Lover''s Leap Trail at Natural Tunnel State Park, looking down toward the limestone tunnel and gorge. Just under a mile round trip with paved sections and stairs. The park opens daily from 8am to dusk.', 'open', null, 'https://www.dcr.virginia.gov/state-parks/natural-tunnel', '2026-09-06T22:43:52.581802+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lover''s Leap Wayside', 'lover-s-leap-wayside', 'folklore', 36.717625, -80.323185, 'Stuart', 'VA', 'A roadside viewpoint on the US 58 mountain crossing in Patrick County, with a stone wall and long views over the Blue Ridge foothills. The name attaches to the local Morning Flower legend. Route 58 construction is still affecting the area in 2026, with access currently routed via Poor Farmers Farm Road.', 'roadside', null, 'https://visitpatrickcounty.org/attractions/lovers-leap/', '2026-09-06T22:43:52.581802+00:00', null, null, null, null, null, 'America/New_York'),
  ('Lovers Leap', 'lovers-leap', 'folklore', 36.424372, -105.002916, 'Cimarron', 'NM', 'Lovers Leap is a cliff at roughly 7,300 feet on Philmont Scout Ranch, looking out over the backcountry and the Tooth of Time. Philmont runs a three-mile round trip to it, but this is ranch property rather than an open viewpoint, so arrange access rather than turning up.', 'limited', null, 'https://philmontscoutranch.org/ptc/activity-descriptions/', '2026-09-06T22:43:52.581802+00:00', null, null, null, null, null, 'America/Denver'),
  ('Lovers Leap Overlook', 'lovers-leap-overlook', 'folklore', 37.281638, -82.288051, 'Breaks', 'VA', 'A Route 80 overlook beside Breaks Interstate Park, looking into the Russell Fork gorge toward the Towers. The legend here has two lovers from warring groups jumping from the rim rather than be separated. It sits outside the park gate, a very short walk from roadside parking.', 'roadside', null, 'https://byway.world/lookouts/lovers-leap-overlook-7e9c2886', '2026-09-06T22:43:52.581802+00:00', null, null, null, null, null, 'America/New_York'),
  ('Manchester Vampire Marker', 'manchester-vampire-marker', 'folklore', 43.17706, -73.0505, 'Manchester Center', 'VT', 'A historical marker near Factory Point Cemetery records the story of Rachel Harris Burton, whose body was reportedly exhumed and burned around 1792 after townspeople feared she had become a vampire. The episode belongs to the documented New England vampire panic surrounding tuberculosis and other unexplained illness.', 'open', null, 'https://www.wgpfoundation.org/historic-markers/manchester-vampire/', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Merchant Ball', 'merchant-ball', 'folklore', 40.57664, -83.12201, 'Marion', 'OH', 'The Merchant family grave at Marion Cemetery is topped by a roughly 5,200-pound granite sphere that has slowly rotated on its pedestal over the decades. No definitive supernatural explanation is needed for the movement, but the visibly shifting stone has become a longstanding cemetery mystery; visit respectfully during cemetery hours.', 'open', null, 'https://www.atlasobscura.com/places/merchant-ball', '2026-09-08T02:02:43.398883+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mile Marker No. 30', 'mile-marker-no-30', 'folklore', 41.155, -72.24116, 'Cutchogue', 'NY', 'Long Island tradition claimed Benjamin Franklin personally placed this stone mileage marker while serving as colonial postmaster in the 1750s. Later research indicates the marker was probably installed in the early nineteenth century, but the Franklin story endured for generations and is now explained by a Legends & Lore marker beside Route 25.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/mile-marker-30/', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('Misty of Chincoteague Statue', 'misty-of-chincoteague-statue', 'folklore', 37.93425, -75.37678, 'Chincoteague', 'VA', 'Marguerite Henry''s 1947 book Misty of Chincoteague turned the island''s pony culture and the real mare Misty into an enduring American children''s legend. A bronze Misty statue donated in 2006 stands along Main Street, giving visitors a physical stop connected to both the famous book and Chincoteague''s pony tradition.', 'open', null, 'https://www.hmdb.org/m.asp?m=181179', '2026-09-08T04:17:48.352537+00:00', null, null, null, null, null, 'America/New_York'),
  ('Moll Dyer Rock', 'moll-dyer-rock', 'folklore', 38.28947, -76.63594, 'Leonardtown', 'MD', 'Local legend says Moll Dyer was driven from her home on a freezing night in the late 1600s after townspeople accused her of witchcraft, and that her frozen body was later found against a large rock. The stone associated with the story was moved in 2021 to Tudor Hall, where it is displayed outside the St. Mary''s County Historical Society.', 'open', null, 'https://www.stmaryshistory.org/content.aspx?club_id=706426&module_id=487754&page_id=22', '2026-09-08T03:44:27.5898+00:00', null, null, null, null, null, 'America/New_York'),
  ('Money Diggers Marker', 'money-diggers-marker', 'folklore', 43.18124, -76.83584, 'North Rose', 'NY', 'During the 1830s, spirit mediums supposedly led groups into this area to dig for buried gold and jewels revealed by supernatural guidance. The legend held that everyone had to remain completely silent while digging or evil spirits would appear and the treasure would vanish; a marker now stands near Galen and Lasher roads.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/money-diggers/', '2026-09-07T16:22:52.387536+00:00', null, null, null, null, null, 'America/New_York'),
  ('Mooresville Gravity Hill', 'mooresville-gravity-hill-mooresville-in', 'folklore', 39.601306, -86.411, 'Mooresville', 'IN', 'Stop on Gravity Hill, outside Mooresville, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Indiana/Indianapolis'),
  ('Moose Lodge Gravity Hill', 'moose-lodge-gravity-hill-bartlesville-ok', 'folklore', 36.670139, -95.98139, 'Bartlesville', 'OK', 'Stop on Moose Lodge Road, near the railway crossing, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Chicago'),
  ('Mountain Springs Gravity Hill', 'mountain-springs-gravity-hill-ocotillo-ca', 'folklore', 32.6789722, -116.0991944, 'Ocotillo', 'CA', 'Stop on the Mountain Springs Road off-ramp from I-8 westbound, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('Mountain Witch of Sugar Loaf', 'mountain-witch-of-sugar-loaf', 'folklore', 41.3155, -74.28789, 'Sugar Loaf', 'NY', 'Local folklore remembers Elizabeth Dobbin, a widow who supposedly lived alone near Sugar Loaf Mountain in the late 1700s and was accused by nearby villagers of practicing witchcraft. A Legends & Lore marker now marks the area associated with the Mountain Witch story.', 'roadside', null, 'https://www.wgpfoundation.org/historic-markers/mountain-witch/', '2026-09-07T16:22:52.387536+00:00', null, null, null, null, null, 'America/New_York'),
  ('Nason Street Gravity Hill', 'nason-street-gravity-hill-moreno-valley-ca', 'folklore', 33.9406944, -117.1916389, 'Moreno Valley', 'CA', 'Stop on Nason Street, heading south just past Elder, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('Nathaniel Knapp Bear Fight Marker', 'nathaniel-knapp-bear-fight-marker', 'folklore', 41.32864, -74.27994, 'Chester', 'NY', 'Local legend says Nathaniel Knapp killed a bear here around 1750 using only a knife and later asked to be buried at the site. The marker stands at Knapp''s View, a public passive park with walking and picnic access, though no confirmed grave marker for Knapp survives.', 'open', null, 'https://www.wgpfoundation.org/historic-markers/nathaniel-knapp/', '2026-09-08T01:35:27.513733+00:00', null, null, null, null, null, 'America/New_York'),
  ('New Harmony Labyrinth', 'new-harmony-labyrinth', 'folklore', 38.12244, -87.93591, 'New Harmony', 'IN', 'The Harmonists who founded New Harmony in the early nineteenth century used a labyrinth as a spiritual symbol of the difficult path toward enlightenment. Today''s hedge labyrinth recreates that tradition around a small temple and is open to visitors year-round without admission.', 'open', null, 'https://www.atlasobscura.com/places/new-harmony-labyrinth', '2026-09-08T13:34:34.826362+00:00', null, null, null, null, null, 'America/Chicago'),
  ('New Prospect Road Gravity Hill', 'new-prospect-road-gravity-hill-jackson-nj', 'folklore', 40.1587778, -74.2676667, 'Jackson', 'NJ', 'Stop on New Prospect Road, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/New_York'),
  ('North Crosby Road Gravity Hill', 'north-crosby-road-gravity-hill-prosser-wa', 'folklore', 46.36222, -119.7238056, 'Prosser', 'WA', 'Stop on North Crosby Road, northeast of town, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Los_Angeles'),
  ('North Park Gravity Hill', 'north-park-gravity-hill-pittsburgh-pa', 'folklore', 40.6126944, -80.0258056, 'Pittsburgh', 'PA', 'Stop on McKinney Road at Kummer Road, in North Park, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/New_York'),
  ('Octavia Hatcher Buried-Alive Grave', 'octavia-hatcher-buried-alive-grave', 'folklore', 37.47963, -82.5193, 'Pikeville', 'KY', 'Local tradition says Octavia Hatcher was mistakenly declared dead in 1891 during an illness that left several Pikeville residents in coma-like states. Her husband later reportedly exhumed her and found evidence she had awakened in the coffin; a fenced statue now marks her grave in Pikeville Cemetery.', 'open', null, 'https://www.roadsideamerica.com/story/23884', '2026-09-08T14:15:10.228298+00:00', null, null, null, null, null, 'America/New_York'),
  ('Old Round Church', 'old-round-church', 'folklore', 44.39888, -72.99907, 'Richmond', 'VT', 'Built in the early nineteenth century, this rare many-sided meetinghouse looks almost circular from a distance. Local lore says its shape left the devil no corner in which to hide, adding a supernatural explanation to one of Vermont''s most unusual historic buildings.', 'limited', null, 'https://www.atlasobscura.com/places/old-round-church', '2026-09-08T16:08:01.377449+00:00', null, null, null, null, null, 'America/New_York'),
  ('Paulding Light Viewing Area', 'paulding-light-viewing-area', 'folklore', 46.40129, -89.17907, 'Watersmeet', 'MI', 'For generations, people have gathered at the end of an old roadway to watch a mysterious light appear in the distance, inspiring stories about a ghostly railroad worker and other supernatural explanations. Experiments have strongly connected the phenomenon to distant vehicle headlights, but the established public viewing area keeps the Paulding Light one of Michigan''s most enduring legend-tripping stops.', 'roadside', null, 'https://www.atlasobscura.com/places/the-paulding-light', '2026-09-08T14:53:55.160019+00:00', null, null, null, null, null, 'America/Detroit'),
  ('Pete the Talking Crow — Georgetown & Scott County Museum', 'pete-the-talking-crow-georgetown-scott-county-museum', 'folklore', 38.21858, -84.55624, 'Georgetown', 'KY', 'Local legend remembers Pete as a real talking crow that supposedly shouted "Go!" during early horse races and helped inspire the use of organized race starts. The Georgetown & Scott County Museum keeps the story alive with a mechanical Pete display among its local-history collections.', 'limited', null, 'https://www.roadsideamerica.com/story/16999', '2026-09-08T14:30:49.642487+00:00', null, 'https://www.georgetownscottcountymuseum.com/', null, null, null, 'America/New_York'),
  ('Pitt Road Gravity Hill', 'pitt-road-gravity-hill-springer-ok', 'folklore', 34.345972, -97.1779444, 'Springer', 'OK', 'Stop on Pitt Road, near Ardmore, put the car in neutral, and it appears to roll uphill. The slope is an illusion — the surrounding land hides the true horizon, so a gentle descent reads as a climb — which has never once stopped anyone trying it with a bottle of water. A public road, so pull over sensibly and watch for traffic.', 'roadside', null, 'https://en.wikipedia.org/wiki/List_of_gravity_hills', '2026-09-06T01:38:36.249959+00:00', null, null, null, null, null, 'America/Chicago'),
